#include <linux/sched/signal.h>

#include <linux/sched/task.h>

#include <linux/mm.h>

#include <linux/vmacache.h>

#include <asm/pgtable.h>



/*

 * Hash based on the pmd of addr if configured with MMU, which provides a good

 * hit rate for workloads with spatial locality.  Otherwise, use pages.

 */

#ifdef CONFIG_MMU

#define VMACACHE_SHIFT	PMD_SHIFT

#else

#define VMACACHE_SHIFT	PAGE_SHIFT

#endif

#define VMACACHE_HASH(addr) ((addr >> VMACACHE_SHIFT) & VMACACHE_MASK)



/*

 * Flush vma caches for threads that share a given mm.

 *

 * The operation is safe because the caller holds the mmap_sem

 * exclusively and other threads accessing the vma cache will

 * have mmap_sem held at least for read, so no extra locking

 * is required to maintain the vma cache.

 */

void vmacache_flush_all(struct mm_struct *mm)

{

	struct task_struct *g, *p;



	count_vm_vmacache_event(VMACACHE_FULL_FLUSHES);



	/*

	 * Single threaded tasks need not iterate the entire

	 * list of process. We can avoid the flushing as well

	 * since the mm's seqnum was increased and don't have

	 * to worry about other threads' seqnum. Current's

	 * flush will occur upon the next lookup.

	 */

	if (atomic_read(&mm->mm_users) == 1)

		return;



	rcu_read_lock();

	for_each_process_thread(g, p) {

		/*

		 * Only flush the vmacache pointers as the

		 * mm seqnum is already set and curr's will

		 * be set upon invalidation when the next

		 * lookup is done.

		 */

		if (mm == p->mm)

			vmacache_flush(p);

	}

	rcu_read_unlock();

}



/*

 * This task may be accessing a foreign mm via (for example)

 * get_user_pages()->find_vma().  The vmacache is task-local and this

 * task's vmacache pertains to a different mm (ie, its own).  There is

 * nothing we can do here.

 *

 * Also handle the case where a kernel thread has adopted this mm via use_mm().

 * That kernel thread's vmacache is not applicable to this mm.

 */

static inline bool vmacache_valid_mm(struct mm_struct *mm)

{

	return current->mm == mm && !(current->flags & PF_KTHREAD);

}



void vmacache_update(unsigned long addr, struct vm_area_struct *newvma)

{

	if (vmacache_valid_mm(newvma->vm_mm))

		current->vmacache.vmas[VMACACHE_HASH(addr)] = newvma;

}



static bool vmacache_valid(struct mm_struct *mm)

{

	struct task_struct *curr;



	if (!vmacache_valid_mm(mm))

		return false;



	curr = current;

	if (mm->vmacache_seqnum != curr->vmacache.seqnum) {

		/*

		 * First attempt will always be invalid, initialize

		 * the new cache for this task here.

		 */

		curr->vmacache.seqnum = mm->vmacache_seqnum;

		vmacache_flush(curr);

		return false;

	}

	return true;

}



struct vm_area_struct *vmacache_find(struct mm_struct *mm, unsigned long addr)

{

	int idx = VMACACHE_HASH(addr);

	int i;



	count_vm_vmacache_event(VMACACHE_FIND_CALLS);



	if (!vmacache_valid(mm))

		return NULL;



	for (i = 0; i < VMACACHE_SIZE; i++) {

		struct vm_area_struct *vma = current->vmacache.vmas[idx];



		if (vma) {

#ifdef CONFIG_DEBUG_VM_VMACACHE

			if (WARN_ON_ONCE(vma->vm_mm != mm))

				break;

#endif

			if (vma->vm_start <= addr && vma->vm_end > addr) {

				count_vm_vmacache_event(VMACACHE_FIND_HITS);

				return vma;

			}

		}

		if (++idx == VMACACHE_SIZE)

			idx = 0;

	}



	return NULL;

}



#ifndef CONFIG_MMU

struct vm_area_struct *vmacache_find_exact(struct mm_struct *mm,

					   unsigned long start,

					   unsigned long end)

{

	int idx = VMACACHE_HASH(start);

	int i;



	count_vm_vmacache_event(VMACACHE_FIND_CALLS);



	if (!vmacache_valid(mm))

		return NULL;



	for (i = 0; i < VMACACHE_SIZE; i++) {

		struct vm_area_struct *vma = current->vmacache.vmas[idx];



		if (vma && vma->vm_start == start && vma->vm_end == end) {

			count_vm_vmacache_event(VMACACHE_FIND_HITS);

			return vma;

		}

		if (++idx == VMACACHE_SIZE)

			idx = 0;

	}



	return NULL;

}

#endif

#include "jsi.h"

#include "jsvalue.h"

#include "jsbuiltin.h"



#if defined(_MSC_VER) && (_MSC_VER < 1700) /* VS2012 has stdint.h */

typedef unsigned __int64 uint64_t;

#else

#include <stdint.h>

#endif



static void jsB_new_Number(js_State *J)

{

	js_newnumber(J, js_gettop(J) > 1 ? js_tonumber(J, 1) : 0);

}



static void jsB_Number(js_State *J)

{

	js_pushnumber(J, js_gettop(J) > 1 ? js_tonumber(J, 1) : 0);

}



static void Np_valueOf(js_State *J)

{

	js_Object *self = js_toobject(J, 0);

	if (self->type != JS_CNUMBER) js_typeerror(J, "not a number");

	js_pushnumber(J, self->u.number);

}



static void Np_toString(js_State *J)

{

	char buf[100];

	js_Object *self = js_toobject(J, 0);

	int radix = js_isundefined(J, 1) ? 10 : js_tointeger(J, 1);

	if (self->type != JS_CNUMBER)

		js_typeerror(J, "not a number");

	if (radix == 10) {

		js_pushstring(J, jsV_numbertostring(J, buf, self->u.number));

		return;

	}

	if (radix < 2 || radix > 36)

		js_rangeerror(J, "invalid radix");



	/* lame number to string conversion for any radix from 2 to 36 */

	{

		static const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";

		double number = self->u.number;

		int sign = self->u.number < 0;

		js_Buffer *sb = NULL;

		uint64_t u, limit = ((uint64_t)1<<52);



		int ndigits, exp, point;



		if (number == 0) { js_pushstring(J, "0"); return; }

		if (isnan(number)) { js_pushstring(J, "NaN"); return; }

		if (isinf(number)) { js_pushstring(J, sign ? "-Infinity" : "Infinity"); return; }



		if (sign)

			number = -number;



		/* fit as many digits as we want in an int */

		exp = 0;

		while (number * pow(radix, exp) > limit)

			--exp;

		while (number * pow(radix, exp+1) < limit)

			++exp;

		u = number * pow(radix, exp) + 0.5;



		/* trim trailing zeros */

		while (u > 0 && (u % radix) == 0) {

			u /= radix;

			--exp;

		}



		/* serialize digits */

		ndigits = 0;

		while (u > 0) {

			buf[ndigits++] = digits[u % radix];

			u /= radix;

		}

		point = ndigits - exp;



		if (js_try(J)) {

			js_free(J, sb);

			js_throw(J);

		}



		if (sign)

			js_putc(J, &sb, '-');



		if (point <= 0) {

			js_putc(J, &sb, '0');

			js_putc(J, &sb, '.');

			while (point++ < 0)

				js_putc(J, &sb, '0');

			while (ndigits-- > 0)

				js_putc(J, &sb, buf[ndigits]);

		} else {

			while (ndigits-- > 0) {

				js_putc(J, &sb, buf[ndigits]);

				if (--point == 0 && ndigits > 0)

					js_putc(J, &sb, '.');

			}

			while (point-- > 0)

				js_putc(J, &sb, '0');

		}



		js_putc(J, &sb, 0);

		js_pushstring(J, sb->s);



		js_endtry(J);

		js_free(J, sb);

	}

}



/* Customized ToString() on a number */

static void numtostr(js_State *J, const char *fmt, int w, double n)

{

	/* buf needs to fit printf("%.20f", 1e20) */

	char buf[50], *e;

	sprintf(buf, fmt, w, n);

	e = strchr(buf, 'e');

	if (e) {

		int exp = atoi(e+1);

		sprintf(e, "e%+d", exp);

	}

	js_pushstring(J, buf);

}



static void Np_toFixed(js_State *J)

{

	js_Object *self = js_toobject(J, 0);

	int width = js_tointeger(J, 1);

	char buf[32];

	double x;

	if (self->type != JS_CNUMBER) js_typeerror(J, "not a number");

	if (width < 0) js_rangeerror(J, "precision %d out of range", width);

	if (width > 20) js_rangeerror(J, "precision %d out of range", width);

	x = self->u.number;

	if (isnan(x) || isinf(x) || x <= -1e21 || x >= 1e21)

		js_pushstring(J, jsV_numbertostring(J, buf, x));

	else

		numtostr(J, "%.*f", width, x);

}



static void Np_toExponential(js_State *J)

{

	js_Object *self = js_toobject(J, 0);

	int width = js_tointeger(J, 1);

	char buf[32];

	double x;

	if (self->type != JS_CNUMBER) js_typeerror(J, "not a number");

	if (width < 0) js_rangeerror(J, "precision %d out of range", width);

	if (width > 20) js_rangeerror(J, "precision %d out of range", width);

	x = self->u.number;

	if (isnan(x) || isinf(x))

		js_pushstring(J, jsV_numbertostring(J, buf, x));

	else

		numtostr(J, "%.*e", width, self->u.number);

}



static void Np_toPrecision(js_State *J)

{

	js_Object *self = js_toobject(J, 0);

	int width = js_tointeger(J, 1);

	char buf[32];

	double x;

	if (self->type != JS_CNUMBER) js_typeerror(J, "not a number");

	if (width < 1) js_rangeerror(J, "precision %d out of range", width);

	if (width > 21) js_rangeerror(J, "precision %d out of range", width);

	x = self->u.number;

	if (isnan(x) || isinf(x))

		js_pushstring(J, jsV_numbertostring(J, buf, x));

	else

		numtostr(J, "%.*g", width, self->u.number);

}



void jsB_initnumber(js_State *J)

{

	J->Number_prototype->u.number = 0;



	js_pushobject(J, J->Number_prototype);

	{

		jsB_propf(J, "Number.prototype.valueOf", Np_valueOf, 0);

		jsB_propf(J, "Number.prototype.toString", Np_toString, 1);

		jsB_propf(J, "Number.prototype.toLocaleString", Np_toString, 0);

		jsB_propf(J, "Number.prototype.toFixed", Np_toFixed, 1);

		jsB_propf(J, "Number.prototype.toExponential", Np_toExponential, 1);

		jsB_propf(J, "Number.prototype.toPrecision", Np_toPrecision, 1);

	}

	js_newcconstructor(J, jsB_Number, jsB_new_Number, "Number", 0); /* 1 */

	{

		jsB_propn(J, "MAX_VALUE", 1.7976931348623157e+308);

		jsB_propn(J, "MIN_VALUE", 5e-324);

		jsB_propn(J, "NaN", NAN);

		jsB_propn(J, "NEGATIVE_INFINITY", -INFINITY);

		jsB_propn(J, "POSITIVE_INFINITY", INFINITY);

	}

	js_defglobal(J, "Number", JS_DONTENUM);

}

/*

 * Description: network buf manager

 *     History: yang@haipo.me, 2016/03/16, create

 */



# include <errno.h>

# include <string.h>

# include "nw_buf.h"



# define NW_BUF_POOL_INIT_SIZE 64

# define NW_BUF_POOL_MAX_SIZE  65535

# define NW_CACHE_INIT_SIZE    64

# define NW_CACHE_MAX_SIZE     65535



size_t nw_buf_size(nw_buf *buf)

{

    return buf->wpos - buf->rpos;

}



size_t nw_buf_avail(nw_buf *buf)

{

    return buf->size - buf->wpos;

}



size_t nw_buf_write(nw_buf *buf, const void *data, size_t len)

{

    size_t available = buf->size - buf->wpos;

    size_t wlen = len > available ? available : len;

    memcpy(buf->data + buf->wpos, data, wlen);

    buf->wpos += wlen;

    return wlen;

}



void nw_buf_shift(nw_buf *buf)

{

    if (buf->rpos == buf->wpos) {

        buf->rpos = buf->wpos = 0;

    } else if (buf->rpos != 0) {

        memmove(buf->data, buf->data + buf->rpos, buf->wpos - buf->rpos);

        buf->wpos -= buf->rpos;

        buf->rpos = 0;

    }

}



nw_buf_pool *nw_buf_pool_create(uint32_t size)

{

    nw_buf_pool *pool = malloc(sizeof(nw_buf_pool));

    if (pool == NULL)

        return NULL;



    pool->size = size;

    pool->used = 0;

    pool->free = 0;

    pool->free_total = NW_BUF_POOL_INIT_SIZE;

    pool->free_arr = malloc(pool->free_total * sizeof(nw_buf *));

    if (pool->free_arr == NULL) {

        free(pool);

        return NULL;

    }



    return pool;

}



nw_buf *nw_buf_alloc(nw_buf_pool *pool)

{

    if (pool->free) {

        nw_buf *buf = pool->free_arr[--pool->free];

        buf->size = pool->size;

        buf->rpos = 0;

        buf->wpos = 0;

        buf->next = NULL;

        return buf;

    }



    nw_buf *buf = malloc(sizeof(nw_buf) + pool->size);

    if (buf == NULL)

        return NULL;

    buf->size = pool->size;

    buf->rpos = 0;

    buf->wpos = 0;

    buf->next = NULL;



    return buf;

}



void nw_buf_free(nw_buf_pool *pool, nw_buf *buf)

{

    if (pool->free < pool->free_total) {

        pool->free_arr[pool->free++] = buf;

    } else if (pool->free_total < NW_BUF_POOL_MAX_SIZE) {

        uint32_t new_free_total = pool->free_total * 2;

        void *new_arr = realloc(pool->free_arr, new_free_total * sizeof(nw_buf *));

        if (new_arr) {

            pool->free_total = new_free_total;

            pool->free_arr = new_arr;

            pool->free_arr[pool->free++] = buf;

        } else {

            free(buf);

        }

    } else {

        free(buf);

    }

}



void nw_buf_pool_release(nw_buf_pool *pool)

{

    for (uint32_t i = 0; i < pool->free; ++i) {

        free(pool->free_arr[i]);

    }

    free(pool->free_arr);

    free(pool);

}



nw_buf_list *nw_buf_list_create(nw_buf_pool *pool, uint32_t limit)

{

    nw_buf_list *list = malloc(sizeof(nw_buf_list));

    if (list == NULL)

        return NULL;

    list->pool = pool;

    list->count = 0;

    list->limit = limit;

    list->head = NULL;

    list->tail = NULL;



    return list;

}



size_t nw_buf_list_write(nw_buf_list *list, const void *data, size_t len)

{

    const void *pos = data;

    size_t left = len;



    if (list->tail && nw_buf_avail(list->tail)) {

        size_t ret = nw_buf_write(list->tail, pos, left);

        left -= ret;

        pos += ret;

    }



    while (left) {

        if (list->limit && list->count >= list->limit)

            return len - left;

        nw_buf *buf = nw_buf_alloc(list->pool);

        if (buf == NULL)

            return len - left;

        if (list->head == NULL)

            list->head = buf;

        if (list->tail != NULL)

            list->tail->next = buf;

        list->tail = buf;

        list->count++;

        size_t ret = nw_buf_write(list->tail, pos, left);

        left -= ret;

        pos += ret;

    }



    return len;

}



size_t nw_buf_list_append(nw_buf_list *list, const void *data, size_t len)

{

    if (list->limit && list->count >= list->limit)

        return 0;

    nw_buf *buf = nw_buf_alloc(list->pool);

    if (buf == NULL)

        return 0;

    if (len > buf->size) {

        nw_buf_free(list->pool, buf);

        return 0;

    }

    nw_buf_write(buf, data, len);

    if (list->head == NULL)

        list->head = buf;

    if (list->tail != NULL)

        list->tail->next = buf;

    list->tail = buf;

    list->count++;



    return len;

}



void nw_buf_list_shift(nw_buf_list *list)

{

    if (list->head) {

        nw_buf *tmp = list->head;

        list->head = tmp->next;

        if (list->head == NULL) {

            list->tail = NULL;

        }

        list->count--;

        nw_buf_free(list->pool, tmp);

    }

}



void nw_buf_list_release(nw_buf_list *list)

{

    nw_buf *curr = list->head;

    nw_buf *next = NULL;

    while (curr) {

        next = curr->next;

        nw_buf_free(list->pool, curr);

        curr = next;

    }

    free(list);

}





nw_cache *nw_cache_create(uint32_t size)

{

    nw_cache *cache = malloc(sizeof(nw_cache));

    if (cache == NULL)

        return NULL;



    cache->size = size;

    cache->used = 0;

    cache->free = 0;

    cache->free_total = NW_CACHE_INIT_SIZE;

    cache->free_arr = malloc(cache->free_total * sizeof(void *));

    if (cache->free_arr == NULL) {

        free(cache);

        return NULL;

    }



    return cache;

}



void *nw_cache_alloc(nw_cache *cache)

{

    if (cache->free)

        return cache->free_arr[--cache->free];

    return malloc(cache->size);

}



void nw_cache_free(nw_cache *cache, void *obj)

{

    if (cache->free < cache->free_total) {

        cache->free_arr[cache->free++] = obj;

    } else if (cache->free_total < NW_CACHE_MAX_SIZE) {

        uint32_t new_free_total = cache->free_total * 2;

        void *new_arr = realloc(cache->free_arr, new_free_total * sizeof(void *));

        if (new_arr) {

            cache->free_total = new_free_total;

            cache->free_arr = new_arr;

            cache->free_arr[cache->free++] = obj;

        } else {

            free(obj);

        }

    } else {

        free(obj);

    }

}



void nw_cache_release(nw_cache *cache)

{

    for (uint32_t i = 0; i < cache->free; ++i) {

        free(cache->free_arr[i]);

    }

    free(cache->free_arr);

    free(cache);

}

